let WindowStart = todatetime('{TimeRange:startISO}');
let WindowEnd = todatetime('{TimeRange:endISO}');
let WindowSpan = WindowEnd - WindowStart;
let Step = case(WindowSpan <= 6h, 10m, WindowSpan <= 2d, 1h, WindowSpan <= 8d, 2h, WindowSpan <= 16d, 6h, 12h);
let Num = (v:real, digits:int) { replace_regex(tostring(round(v, digits)), @"\.0+$", "") };
let AgeText = (ts:datetime) {
    let mins = datetime_diff('minute', now(), ts);
    case(isnull(ts), 'none', mins < 2, 'just now', mins < 120, strcat(mins, ' min ago'), mins < 2880, strcat(Num(mins / 60.0, 1), ' h ago'), strcat(Num(mins / 1440.0, 1), ' d ago'))
};
let Worker = Event
| where TimeGenerated between (WindowStart .. WindowEnd) and Source == 'ArcSqlEngineDemo' and EventID in (6000, 6001, 6201)
| extend Detail = iff(EventID == 6000, RenderedDescription, '')
| extend Elapsed = todouble(extract(@'elapsedMs=(\d+)', 1, Detail)), LastCommit = todatetime(extract(@'lastCommitUtc=([0-9T:\.\-Z]+)', 1, Detail)), Database = extract(@'database=([^ ]+)', 1, Detail);
let Healthy = Worker | where EventID == 6000;
let LastEvent = toscalar(Healthy | summarize max(TimeGenerated));
let LastCommit = toscalar(Healthy | summarize max(LastCommit));
let LastHost = toscalar(Healthy | summarize arg_max(TimeGenerated, Computer) | project Computer);
let LastDb = toscalar(Healthy | summarize arg_max(TimeGenerated, Database) | project Database);
let Recent = Healthy | where TimeGenerated > LastEvent - 1h | summarize N = count(), SpanMin = (max(TimeGenerated) - min(TimeGenerated)) / 1m, AvgMs = avg(Elapsed), MaxMs = max(Elapsed);
let Rate = toscalar(Recent | extend R = N / (SpanMin + 1.0) | project R);
let AvgMs = toscalar(Recent | project AvgMs);
let MaxMs = toscalar(Recent | project MaxMs);
let Incidents = Worker | where EventID == 6201 | summarize Count = count(), Last = max(TimeGenerated);
let IncidentCount = toscalar(Incidents | project Count);
let LastIncident = toscalar(Incidents | project Last);
let HasWork = isnotnull(LastEvent);
print Dummy = 1
| project data = pack_array(
    pack('Label', 'Last commit', 'Value', iff(HasWork, AgeText(LastCommit), 'No events'), 'Note', iff(HasWork, strcat(LastHost, ' / ', LastDb), 'no events in this range'), 'Order', 1),
    pack('Label', 'Commit events/min', 'Value', iff(HasWork, Num(Rate, 1), 'No events'), 'Note', iff(HasWork, 'healthy commit and read (6000)', 'no events in this range'), 'Order', 2),
    pack('Label', 'Commit latency', 'Value', iff(HasWork, strcat(Num(AvgMs, 0), ' ms'), 'No events'), 'Note', iff(HasWork, strcat('slowest ', Num(MaxMs, 0), ' ms, last hour'), 'no events in this range'), 'Order', 3),
    pack('Label', 'Lock timeouts', 'Value', tostring(coalesce(IncidentCount, 0)), 'Note', 'SQL error 1222 in range', 'Order', 4),
    pack('Label', 'Last lock timeout', 'Value', iff(isnotnull(LastIncident), AgeText(LastIncident), 'None in range'), 'Note', iff(isnotnull(LastIncident), 'event 6201 on the SQL host', 'no 6201 events in range'), 'Order', 5))
| mv-expand data
| project Label = tostring(data.Label), Value = tostring(data.Value), Note = tostring(data.Note), Order = toint(data.Order)
| order by Order asc
| project Label, Value, Note

