let Detected = Event
| where TimeGenerated between (WindowStart .. WindowEnd) and Source == 'ArcSqlEngineDemo' and EventID == 6201
| extend j = parse_json(RenderedDescription)
| project Detected = TimeGenerated, SqlHost = Computer, IncidentId = tostring(j.incidentId), Database = tostring(j.database), VictimSession = toint(j.victimSessionId), BlockerSession = toint(j.blockerSessionId),
    WaitType = tostring(j.waitType);
let Recovered = Event
| where TimeGenerated between (WindowStart .. WindowEnd + 1h) and Source == 'ArcSqlEngineDemo' and EventID == 6001
| extend j = parse_json(RenderedDescription)
| project Recovered = TimeGenerated, IncidentId = tostring(j.incidentId);
Detected
| join kind=leftouter Recovered on IncidentId
| extend RecoveredAfterSec = datetime_diff('second', Recovered, Detected)
| order by Detected desc
| take 25
| project Detected, SqlHost, Database, WaitType, VictimSession, BlockerSession, RecoveredAfterSec

